WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, order_id ORDER BY amount DESC NULLS LAST, id) AS latest_rank FROM payments) ranked WHERE latest_rank = 1) SELECT status, DATE_TRUNC('WEEK', paid_at) AS week_start, COUNT(CASE WHEN method = 'bank_transfer' THEN 1 END) AS bank_transfer_count, MIN(paid_at) AS first_seen, AVG(amount) FILTER (WHERE status = 'FAILED') AS failed_avg_amount FROM ranked GROUP BY 1, 2;
